(function(){"use strict";const n=document.querySelector('#feature-program-list[data-ssr="true"]');n&&n.querySelectorAll(".program-slide-card").forEach(e=>{const t=e.querySelector("[data-program-icon]");t&&window.GenBIApp?.icon&&(t.innerHTML=window.GenBIApp.icon(t.dataset.programIcon||"sparkles","program-icon-svg"));let r=[];try{r=JSON.parse(e.dataset.programSlides||"[]").filter(i=>typeof i=="string"&&i!=="")}catch{r=[]}if(r.length===0||(e.style.setProperty("--program-bg-image",`url('${r[0]}')`),r.length<2))return;let o=0;window.setInterval(()=>{o=(o+1)%r.length,e.style.setProperty("--program-bg-image",`url('${r[o]}')`)},4200)})})();
